const claim = $('Claim Pending').first().json;
const tok = $('Make Tokens').first().json;
const bin = $input.first().binary;
const hasImage = !!(bin && bin.data);
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const site = 'https://threetotango.canimi.app';
const link = (a, t) => esc(site + '/gallery/mod?id=' + encodeURIComponent(tok.id) + '&a=' + a + '&t=' + encodeURIComponent(t));
const isTest = /@ttw-test\.invalid$/i.test(String(claim.email || ''));
const rawName = String(claim.cat_name || 'A cat').replace(/[\r\n]+/g, ' ');
const subject = (isTest ? '[TEST] ' : '') + 'Gallery: ' + rawName + ' wants in';
const name = esc(rawName);
const scene = esc(claim.scene || '');
const btn = 'display:inline-block;padding:12px 22px;border-radius:8px;font-weight:bold;text-decoration:none;font-family:Arial,sans-serif;';
const html = '<div style="font-family:Arial,sans-serif;max-width:480px;margin:0 auto;color:#222">'
  + '<h2 style="margin:0 0 8px">' + name + ' wants in</h2>'
  + '<p style="margin:0 0 12px;color:#666">Scene: ' + scene + '</p>'
  + (hasImage ? '<p><img src="cid:data" alt="' + name + '" style="width:100%;max-width:480px;border-radius:8px"></p>' : '<p style="color:#a00">(image could not be loaded)</p>')
  + '<p style="margin:16px 0">'
  + '<a href="' + link('approve', tok.modToken) + '" style="' + btn + 'background:#E1AD01;color:#222">Approve</a> '
  + '<a href="' + link('reject', tok.modToken) + '" style="' + btn + 'background:#eee;color:#222">Reject</a>'
  + '</p>'
  + '<p style="font-size:12px;color:#888"><a href="' + link('remove', tok.removeToken) + '" style="color:#888">Remove later</a></p>'
  + '</div>';
return [{ json: { subject, html, hasImage }, binary: hasImage ? { data: bin.data } : {} }];
